import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BPKcPtvA.js";const r="/images/envato-theme-update.png",c=JSON.parse('{"title":"Updating Your Theme","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/update-theme.md","filePath":"how-to/update-theme.md"}'),i={name:"how-to/update-theme.md"};function l(s,e,u,h,d,m){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="updating-your-theme" tabindex="-1">Updating Your Theme <a class="header-anchor" href="#updating-your-theme" aria-label="Permalink to &quot;Updating Your Theme&quot;">​</a></h1><h2 id="automatic-update-via-wolfthemes-com-freemius" tabindex="-1">Automatic Update via wolfthemes.com (Freemius) <a class="header-anchor" href="#automatic-update-via-wolfthemes-com-freemius" aria-label="Permalink to &quot;Automatic Update via wolfthemes.com (Freemius)&quot;">​</a></h2><p>Once your license is activated, Freemius handles update checks automatically. You will be notified right in your WordPress admin dashboard whenever a new version is available, with a one-click update link — no manual download needed.</p><h2 id="automatic-update-via-envato-market-plugin-themeforest" tabindex="-1">Automatic Update via Envato Market Plugin (ThemeForest) <a class="header-anchor" href="#automatic-update-via-envato-market-plugin-themeforest" aria-label="Permalink to &quot;Automatic Update via Envato Market Plugin (ThemeForest)&quot;">​</a></h2><p>The easiest way to keep a ThemeForest-purchased theme up to date is with the <a href="https://github.com/envato/wp-envato-market" target="_blank" rel="noreferrer">Envato Market plugin</a>.</p><p>You should be invited to install and activate it on theme activation (on all recent themes). Once installed, go to the Envato Market panel and follow the instructions to connect your Envato account.</p><p><img src="'+r+'" alt="Envato Theme Update"></p><p><strong>You will be notified in your admin dashboard every time a new version is available. Simply follow the link and update in a single click.</strong></p><p>If you <a href="https://github.com/envato/wp-envato-market/issues/124" target="_blank" rel="noreferrer">can&#39;t update from the Envato Market panel</a>, try updating via <strong>Dashboard &gt; Updates</strong> or <strong>Appearance &gt; Themes</strong> instead.</p><p><em>Envato tutorial: <a href="http://envato.com/blog/install-themeforest-wordpress-theme/" target="_blank" rel="noreferrer">Install and update your theme with the Envato Market Plugin</a> (option 3)</em></p><h2 id="manual-update" tabindex="-1">Manual Update <a class="header-anchor" href="#manual-update" aria-label="Permalink to &quot;Manual Update&quot;">​</a></h2><p>If automatic updates are not working at all, you can update manually:</p><ol><li>Download the latest theme package from your Freemius account (if purchased on wolfthemes.com), or from your <a href="https://themeforest.net/downloads" target="_blank" rel="noreferrer">ThemeForest Downloads</a> if purchased there.</li><li>Navigate to <strong>Appearance &gt; Themes</strong> in your WordPress admin.</li><li>Uninstall the current theme version.</li><li>Re-install the new theme version as you did when you first purchased it.</li></ol><p>You will not lose any content or settings by updating this way.</p>',14)])])}const f=t(i,[["render",l]]);export{c as __pageData,f as default};
